dtsPropsFor.PageShell:
children: React.ReactNode;
  /** Centreert de inhoud; 7xl is de standaardbreedte van een Branddock-pagina. */
  maxWidth?: '3xl' | '5xl' | '7xl' | 'full';
  className?: string;
  /** Padding wordt automatisch toegepast. Zet op true voor custom layouts. */
  noPadding?: boolean;

dtsPropsFor.PageHeader:
/** Bepaalt icoon en gradient van de module. */
  moduleKey: 'dashboard' | 'brand-foundation' | 'business-strategy' | 'brandstyle' | 'brandvoice' | 'personas' | 'products' | 'competitors' | 'trend-radar' | 'knowledge' | 'brand-alignment' | 'campaigns' | 'content-library' | 'research' | 'settings' | 'help' | 'media-library' | 'ai-trainer' | 'ai-studio' | 'agents';
  title: string;
  subtitle?: string;
  /** Overschrijft het icoon dat moduleKey normaal kiest. */
  icon?: React.ComponentType<{ className?: string }>;
  /** Knoppen rechts in de header. */
  actions?: React.ReactNode;
  /** Extra inhoud onder de titelregel. */
  children?: React.ReactNode;
  /** Compacte variant: minder padding, kleinere titel. */
  compact?: boolean;
  className?: string;

dtsPropsFor.WizardStepper:
steps: Array<{ id: string; label: string; description?: string }>;
  /** Nul-geindexeerd; stappen ervoor tonen een vinkje. */
  currentStep: number;
  /** Alleen bezochte stappen zijn klikbaar. */
  onStepClick?: (index: number) => void;
  className?: string;

dtsPropsFor.StatGrid:
children: React.ReactNode;
  /** Standaard 4 kolommen. */
  columns?: 2 | 3 | 4;
  className?: string;

dtsPropsFor.SectionCard:
icon?: React.ComponentType<{ className?: string }>;
  title: string;
  subtitle?: string;
  /** Toont een gekleurde impact-badge rechtsboven. */
  impactBadge?: 'high' | 'medium' | 'low';
  /** Tailwind-gradientklassen voor de icoonhouder. */
  iconGradient?: string;
  actions?: React.ReactNode;
  children: React.ReactNode;
  className?: string;

dtsPropsFor.SelectionCard:
icon?: React.ComponentType<{ className?: string }>;
  title: string;
  subtitle?: string;
  selected?: boolean;
  onSelect: () => void;
  /** Extra badges of metadata onder de subtitel. */
  badges?: React.ReactNode;
  /** radio = enkelvoudige keuze, checkbox = meervoudig. */
  selectionMode?: 'radio' | 'checkbox';
  children?: React.ReactNode;
  className?: string;
  testId?: string;

dtsPropsFor.ContentSidebarLayout:
children: React.ReactNode;
  sidebar: React.ReactNode;
  /** sm = 320px, md = 384px. */
  sidebarWidth?: 'sm' | 'md';
  className?: string;

dtsPropsFor.DetailHeader:
onBack: () => void;
  backLabel?: string;
  title: string;
  subtitle?: string;
  /** Badge-elementen naast de titel. */
  badges?: React.ReactNode;
  /** Actieknoppen rechts. */
  actions?: React.ReactNode;
  /** Avatar- of icoonelement links. */
  avatar?: React.ReactNode;

dtsPropsFor.FilterBar:
searchValue: string;
  onSearchChange: (value: string) => void;
  searchPlaceholder?: string;
  /** Filter-dropdowns als children. */
  filters?: React.ReactNode;
  viewMode?: 'grid' | 'list';
  onViewModeChange?: (mode: 'grid' | 'list') => void;
  /** Extra acties rechts. */
  actions?: React.ReactNode;
  className?: string;

dtsPropsFor.IssueCard:
severity: 'critical' | 'warning' | 'suggestion';
  title: string;
  /** Bijv. "Personas -> Tech-Savvy Millennial". */
  subtitle?: string;
  description: string;
  /** Tags die tonen waarmee dit conflicteert. */
  conflictsWith?: string[];
  /** AI-aanbeveling onderaan de kaart. */
  recommendation?: string;
  actions?: React.ReactNode;
  className?: string;

dtsPropsFor.GradientBanner:
/** Bepaalt de gradientkleuren van de banner. */
  moduleKey: 'dashboard' | 'brand-foundation' | 'business-strategy' | 'brandstyle' | 'brandvoice' | 'personas' | 'products' | 'competitors' | 'trend-radar' | 'knowledge' | 'brand-alignment' | 'campaigns' | 'content-library' | 'research' | 'settings' | 'help' | 'media-library' | 'ai-trainer' | 'ai-studio' | 'agents';
  /** Inhoud binnen het gradientvlak (avatar, titel). */
  children?: React.ReactNode;
  height?: 'sm' | 'md' | 'lg';
  className?: string;

dtsPropsFor.FavoriteButton:
isFavorite: boolean;
  onToggle: () => void;
  size?: 'sm' | 'md';
  className?: string;
